// Existing particle attributes and CRT rand composed with actual required-thread acquisition and its allocation/initializer children. No new address credit. Finite prepared gravity inputs; imported Win32 endpoints remain explicit.
using System;namespace Recovered.Gameplay {public static class PtlRuntimeAttributesCPU {static Func<SoundSetupImage,uint,uint[],uint> Route(Func<SoundSetupImage,uint,uint[],uint> leaf){return delegate(SoundSetupImage m,uint address,uint[] args){if(address==0x6f040c)return PtlRuntimeThreadCPU.Required(m,leaf);return leaf(m,address,args);};}public static uint Random(SoundSetupImage m,Func<SoundSetupImage,uint,uint[],uint> leaf){return PtlParticleAttributes.CrtRandom(m,Route(leaf));}public static void Gravity(SoundSetupImage m,uint record,uint particle,Func<SoundSetupImage,uint,uint[],uint> leaf){PtlParticleAttributes.Gravity(m,record,particle,Route(leaf));}public static uint Invoke(SoundSetupImage m,uint address,uint[] args,Func<SoundSetupImage,uint,uint[],uint> leaf){return PtlParticleAttributes.Invoke(m,address,args,Route(leaf));}}}